// 1. Синтаксическая — не скомпилируется
Console.WriteLine("Привет")     // забыта ;

// 2. Логическая — компилируется, но результат неверный
int average = (a + b) / 3;      // делителей должно быть 2

// 3. Времени выполнения — падает при работе
int n = Convert.ToInt16("абв"); // пользователь ввёл не число

try
{
    Console.Write("Please Enter A Number: ");
    double num1 = Convert.ToInt16(Console.ReadLine());

    Console.Write("Now Enter Another Number: ");
    double num2 = Convert.ToInt16(Console.ReadLine());

    Console.WriteLine("Total: " + (num1 + num2));
}
catch (Exception error)
{
    Console.WriteLine(error.Message);
}

try
{
    int[] a = new int[3];
    a[5] = 1;                 // IndexOutOfRangeException
    int x = 10 / 0;           // DivideByZeroException
    int y = Convert.ToInt16("abc");  // FormatException
}
catch (Exception error)
{
    Console.WriteLine(error.Message);
}

try
{
    // рискованный код
}
catch (Exception error)
{
    Console.WriteLine(error.Message);
}
finally
{
    Console.WriteLine("Выполнится в любом случае");
}

